[
  {
    "name": "雪岭庄园外观",
    "description": "建在雪山半腰的维多利亚式石砌庄园，被暴雪包围",
    "visualStyle": "灰白天色，大雪纷飞，庄园窗户透出昏黄灯光，整体阴郁压抑，电影级宽银幕构图"
  },
  {
    "name": "庄园大厅",
    "description": "挑高穹顶的会客大厅，水晶吊灯、壁炉、鹿头标本、老式电话",
    "visualStyle": "暗黄台灯与壁炉火光为主光源，深棕色木饰，对称构图"
  },
  {
    "name": "二楼书房（命案现场）",
    "description": "死者被发现的房间，红木书桌、落地窗、波斯地毯、壁炉",
    "visualStyle": "冷蓝色月光从窗外射入，壁炉余烬微红，明暗对比强烈"
  },
  {
    "name": "餐厅",
    "description": "长条橡木餐桌，六把高背椅，烛台",
    "visualStyle": "烛光摇曳，墙面油画被阴影切割，古典油画质感"
  },
  {
    "name": "走廊与楼梯",
    "description": "纵深极深的橡木走廊，红地毯",
    "visualStyle": "顶灯在尽头形成强透视点，墙面挂肖像，光影斑驳"
  }
]
